#nullable enable // autogenerated

using MVZ2.Vanilla.Entities;
using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Modifiers;

namespace MVZ2.GameContent.Buffs.Projectiles
{
    [AutoBuffDefinition(VanillaBuffNames.Projectile.cattailProjectile)]
    public class CattailProjectileBuff : BuffDefinition
    {
        public CattailProjectileBuff(string nsp, string name) : base(nsp, name)
        {
            AddModifier(new IntModifier(VanillaEntityProps.WATER_INTERACTION, IntegerOperator.Set, WaterInteraction.NONE));
        }
    }
}
